import sys


def print_values(*values, sep=" ", end="\n", stream=None):
    """把多个值拼接后写到指定输出流，默认写到标准输出。

    参数:
        *values: 任意个待打印的值，会依次转为字符串。
        sep:     值之间的分隔符，默认一个空格。
        end:     结尾字符，默认换行符。
        stream:  输出流对象，需支持 write()，默认 sys.stdout。

    返回:
        实际写入的字符串，方便测试或复用。
    """
    out = stream if stream is not None else sys.stdout
    text = sep.join(str(v) for v in values) + end
    out.write(text)
    return text
```

用法：

```python
print_values("hello", "world")                 # hello world
print_values(1, 2, 3, sep=", ")                # 1, 2, 3
print_values("no newline", end="")             # 不换行

import io
buf = io.StringIO()
print_values("captured", stream=buf)
print(repr(buf.getvalue()))                    # 'captured\n'
```

